def err(a, v):
    r = a @ fit(a, v) - v
    h = np.sum(a * np.linalg.pinv(a).T, axis=1)
    return (np.mean(abs(r)), np.mean(abs(r) / np.maximum(1e-09, 1 - h[:, None])))

def c2fit(u, v):
    from scipy.optimize import least_squares
    out = []
    for (key, fun) in [('rat2', lambda u, k: u * u / (1 + k * u * u)), ('rat1', lambda u, k: u * u / (1 + k * abs(u))), ('cos', lambda u, k: np.cos(k * u)), ('atan', lambda u, k: np.arctan(k * u * u)), ('abs', lambda u, k: abs(u)), ('sqrt', lambda u, k: np.sqrt(1 + k * u * u)), ('exp', lambda u, k: np.exp(-k * u * u))]:
        for mode in (0, 1, 2):

            def f(z, p):
                q = fun(z, np.exp(p[0]))
                return d(z, q) if mode == 0 else d(z, z * z, q) if mode == 1 else d(z + p[1] * q)

            def r(p):
                a = f(u, p)
                return (a @ fit(a, v) - v).ravel()
            p = least_squares(r, [-1.5] if mode != 2 else [-1.5, 0.45], bounds=([-4] if mode != 2 else [-4, -5], [2] if mode != 2 else [2, 5])).x
            a = f(u, p)
            out.append((err(a, v)[1], key, mode, p, fit(a, v), err(a, v)[0]))
    return sorted(out, key=lambda a: a[0])

def _operator(panel, key, x, kind):
    from scipy.special import erf
    from scipy.optimize import least_squares
    (u, v) = (np.asarray(panel[k], float) for k in ('u', key))

    def features(q, p):
        (k, a, b) = p[:3]
        if kind == 'b':
            z = erf(np.exp(k) * q + a * q ** 3) + b * q ** 3 + p[3] * q
        else:
            z = q * abs(q) / (1 + np.exp(k) * abs(q)) + a * q ** 3 + b * q
        return np.column_stack((np.ones(len(q)), z))

    def fit(p):
        d = features(u, p)
        coef = np.linalg.lstsq(d, v, rcond=None)[0]
        return ((d @ coef - v).ravel(), coef)
    initial = [0.63, 4.0, -0.62, -2.13] if kind == 'b' else [-0.42, -0.02, -1.08]
    pars = least_squares(lambda p: fit(p)[0], initial, max_nfev=200).x
    return features(x, pars) @ fit(pars)[1]
